Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <algorithm>
#include <cstring>

#define N 15
#define M 100005
using namespace std;
const int INF = 1e9;
const int delta[4][2] = {{0,1},{0,-1},{-1,0},{1,0}};
char maze[N][N], S[N][N];
int i, j, start_x, start_y, s, e, n, t, total, id[N][N], dist[N][N], visited[N][N], q[M], head[N*N*2], tail[N*N*2];
int k1 = 1;
struct Edge { int to, prev, flow; } edges[M];
int Dis[N][N];
struct Point { int x, y; } Q[100005];

inline int bfs()
{
    int i, p, l, r;
    memset(dist, -1, sizeof(dist));
    l = r = 1;
    dist[s] = 0;
    q[1] = s;
    while (l <= r)
    {
        p = q[l];
        for (i = head[p]; i; i = edges[i].prev)
            if (edges[i].flow > 0)
                if (dist[edges[i].to] == -1)
                {
                    q[++r] = edges[i].to;
                    dist[edges[i].to] = dist[p] + 1;
                }
        l++;
    }
    return dist[e] != -1;
}

void add_edge(int p1, int p2, int p3)
{
    edges[++k1].to = p2;
    edges[k1].flow = p3;
    edges[k1].prev = head[p1];
    head[p1] = k1;
    edges[++k1].to = p1;
    edges[k1].flow = 0;
    edges[k1].prev = head[p2];
    head[p2] = k1;
}

int dfs(int node, int flow)
{
    int i, a, total_flow = 0;
    if (node == e) return flow;
    for (i = head[node]; i && flow; i = edges[i].prev)
        if (edges[i].flow > 0 && dist[edges[i].to] == dist[node] + 1)
            if (a = dfs(edges[i].to, min(edges[i].flow, flow)))
            {
                edges[i].flow -= a;
                edges[i ^ 1].flow += a;
                flow -= a;
                total_flow += a;
            }
    if (!total_flow) dist[node] = 1000000000;
    return total_flow;
}

int max_flow()
{
    int total_flow = 0, flow;
    while (bfs())
    {
        flow = dfs(s, 1000000000);
        while (flow)
        {
            total_flow += flow;
            flow = dfs(s, 1000000000);
        }
    }
    return total_flow;
}

bool check_cell(int x, int y)
{
    if (x < 0 || y < 0 || x >= n || y >= n || visited[x][y] || maze[x][y] < '0' || maze[x][y] > '9') return false;
    return true;
}

void run_bfs()
{
    int l = 1, r = 0;
    memset(dist, 60, sizeof(dist));
    dist[start_x][start_y] = 0;
    Q[++r].x = start_x;
    Q[r].y = start_y;
    visited[start_x][start_y] = 1;
    for (; l <= r; ++l)
    {
        int ax = Q[l].x, ay = Q[l].y;
        for (i = 0; i < 4; ++i)
            if (check_cell(ax + delta[i][0], ay + delta[i][1]))
            {
                dist[ax + delta[i][0]][ay + delta[i][1]] = dist[ax][ay] + 1;
                visited[ax + delta[i][0]][ay + delta[i][1]] = 1;
                Q[++r].x = ax + delta[i][0];
                Q[r].y = ay + delta[i][1];
            }
    }
}

void find_paths(int tx, int ty, int idx)
{
    int i, l = 1, r = 0, j;
    Q[++r].x = tx;
    Q[r].y = ty;
    memset(visited, 0, sizeof(visited));
    memset(Dis, 60, sizeof(Dis));
    visited[tx][ty] = 1;
    Dis[tx][ty] = 0;
    for (; l <= r; ++l)
    {
        int ax = Q[l].x, ay = Q[l].y;
        for (i = 0; i < 4; ++i)
            if (check_cell(ax + delta[i][0], ay + delta[i][1]))
            {
                Dis[ax + delta[i][0]][ay + delta[i][1]] = Dis[ax][ay] + 1;
                visited[ax + delta[i][0]][ay + delta[i][1]] = 1;
                if (Dis[ax + delta[i][0]][ay + delta[i][1]] < dist[ax + delta[i][0]][ay + delta[i][1]])
                    Q[++r].x = ax + delta[i][0], Q[r].y = ay + delta[i][1];
            }
    }
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            if (Dis[i][j] <= t && S[i][j] > '0' && S[i][j] <= '9' && Dis[i][j] <= dist[i][j])
                add_edge(idx, id[i][j] + total, INF);
}

int main()
{
    scanf("%d%d", &n, &t);
    for (i = 0; i < n; ++i) scanf("%s", maze[i]);
    for (i = 0; i < n; ++i) scanf("%s", S[i]);
    for (start_x = 0; start_x < n; ++start_x)
    {
        for (start_y = 0; start_y < n; ++start_y)
            if (maze[start_x][start_y] == 'Z') break;
        if (start_y != n) break;
    }
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j) id[i][j] = ++total;
    s = 2 * total + 1;
    e = s + 1;
    run_bfs();
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            if (S[i][j] > '0' && S[i][j] <= '9')
            {
                add_edge(s, id[i][j], S[i][j] - '0');
                find_paths(i, j, id[i][j]);
            }
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            if (S[i][j] > '0' && S[i][j] <= '9') add_edge(id[i][j] + total, e, S[i][j] - '0');
    printf("%d\n", max_flow());
}
